import { existsSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { join } from "node:path";

const require = createRequire(import.meta.url);
const webpush = require("web-push");

const target = join(process.cwd(), ".env.local");

if (existsSync(target)) {
  console.log(".env.local already exists; leaving it untouched.");
  console.log("Remove it first if you want to generate new VAPID keys.");
  process.exit(0);
}

const keys = webpush.generateVAPIDKeys();

const contents = [
  "# Generated by npm run setup:vapid. Do not commit this file.",
  `NEXT_PUBLIC_VAPID_PUBLIC_KEY=${keys.publicKey}`,
  `VAPID_PRIVATE_KEY=${keys.privateKey}`,
  "VAPID_SUBJECT=mailto:hello@memento.local",
  "PUSH_SEND_TOKEN=",
  "",
].join("\n");

writeFileSync(target, contents, { mode: 0o600 });
console.log(`Wrote VAPID keys to ${target}`);
